public int shipWithinDays(int[] weights, int days) {
    int low = max(weights), high = sum(weights), ans = high;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (daysNeeded(weights, mid) <= days) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}

private int daysNeeded(int[] weights, int capacity) {
    int days = 1, load = 0;
    for (int w : weights) {
        if (load + w > capacity) {
            days++;
            load = w;
        } else {
            load += w;
        }
    }
    return days;
}
